# 1. Header / structure checks
if len(fields) != EXPECTED_COLS:
    log("column_count", "WARN", detail=f"Expected {EXPECTED_COLS}, found {len(fields)}")

for c in fields[fields.duplicated()]:
    log("duplicate_column", "ERROR", column=c)
for i, c in enumerate(fields):
    if c in ("nan", "", "None"):
        log("blank_column_name", "ERROR", detail=f"Column index {i}")

prov_re = re.compile(r"^(.*)\s\((horizon|spreadsheet)\)$", re.I)
for i, (f, p) in enumerate(zip(fields, provenance)):
    if f == "Case reference" or pd.isna(p):
        continue
    m = prov_re.match(str(p).strip())
    if not m:
        log("provenance_format", "WARN", column=f, value=p, detail="Row 3 not '<field> (horizon|spreadsheet)'")
    elif m.group(1).strip().lower() != f.lower():
        log("provenance_mismatch", "WARN", column=f, value=p, detail="Provenance label doesn't match field name")

blank_rows = df.drop(columns="_excel_row").isna().all(axis=1)
for r in df.loc[blank_rows, "_excel_row"]:
    log("blank_row", "INFO", row=r)
df = df[~blank_rows].reset_index(drop=True)

# 2. Case reference checks
REF_RE = re.compile(r"^S62A/(\d{4})/(\d{4}|\d{7})(RD)?$")
CR = "Case reference"
df[CR] = df[CR].astype(str).str.strip()

def ref_class(r):
    m = REF_RE.match(r)
    if not m:
        return "INVALID"
    if m.group(3):
        return "REDETERMINATION"
    return "PRE_APP" if len(m.group(2)) == 7 else "APPLICATION"

df["_ref_class"] = df[CR].map(ref_class)
df["_ref_year"]  = df[CR].str.extract(r"^S62A/(\d{4})/")[0]

for _, r in df[df[CR].isin(["nan", "None", ""])].iterrows():
    log("case_ref_null", "ERROR", row=r._excel_row, column=CR)
for _, r in df[df["_ref_class"] == "INVALID"].iterrows():
    log("case_ref_pattern", "ERROR", r[CR], r._excel_row, CR, r[CR], "Not S62A/YYYY/NNNN - excluded from scope")
for _, r in df[df["_ref_class"] == "REDETERMINATION"].iterrows():
    log("case_ref_redetermination", "WARN", r[CR], r._excel_row, CR, r[CR], "RD suffix - confirm handling")
for ref, g in df[df[CR].duplicated(keep=False)].groupby(CR):
    log("case_ref_duplicate", "ERROR", ref, ",".join(map(str, g._excel_row)), CR, detail=f"{len(g)} occurrences")

# Cross-check against Template sheet
if "Template" in xl.sheet_names:
    t = pd.read_excel(xl, sheet_name="Template", header=None, dtype=object)
    t_refs = set(t.iloc[4:, 0].dropna().astype(str).str.strip())
    f_refs = set(df[CR])
    for ref in sorted(t_refs - f_refs):
        log("template_reconciliation", "WARN", ref, detail="In Template, missing from Final selected")
    for ref in sorted(f_refs - t_refs):
        log("template_reconciliation", "WARN", ref, detail="In Final selected, missing from Template")

# 5. Date checks (Horizon cols arrive as dd/mm/yyyy strings, spreadsheet cols as datetimes)
def to_date(v):
    if pd.isna(v) or str(v).strip() == "": return pd.NaT
    if isinstance(v, (datetime, pd.Timestamp)): return pd.Timestamp(v)
    return pd.to_datetime(str(v).strip(), dayfirst=True, errors="coerce")

today, floor = pd.Timestamp.utcnow().tz_localize(None).normalize(), pd.Timestamp(MIN_VALID_DATE)
parsed = {}
for c in DATE_COLS:
    parsed[c] = df[c].map(to_date)
    for i, v in df[c].items():
        if pd.isna(v) or str(v).strip() == "": continue
        d, ref, row = parsed[c][i], df.at[i, CR], df.at[i, "_excel_row"]
        if pd.isna(d):
            log("date_unparseable", "ERROR", ref, row, c, v)
        elif d < floor:
            log("date_too_old", "WARN", ref, row, c, d.date(), f"Before {MIN_VALID_DATE}")
        elif d > today:
            log("date_in_future", "WARN", ref, row, c, d.date(), "All legacy cases should be closed")
        if isinstance(v, str) and not re.match(r"^\d{2}/\d{2}/\d{4}$", v.strip()) and not pd.isna(d):
            log("date_nonstandard_format", "INFO", ref, row, c, v)

# 6. Numeric, Yes/No, email, postcode checks
def to_num(v):
    if pd.isna(v): return None
    if isinstance(v, (int, float)): return float(v)
    t = re.sub(r"[£,\s]", "", str(v)).rstrip(".")
    try: return float(t)
    except ValueError: return "BAD"

ARRAY_RE = re.compile(r"^\[(.*)\]$")
def split_array(v):
    m = ARRAY_RE.match(str(v).strip())
    return [x.strip() for x in m.group(1).split(",")] if m else None

for c in NUMERIC_COLS:
    for i, v in df[c].items():
        ref, row = df.at[i, CR], df.at[i, "_excel_row"]
        arr = split_array(v) if not pd.isna(v) else None
        vals = arr if arr is not None else [v]
        if arr is not None:
            log("multi_value_array", "INFO", ref, row, c, v, "Horizon repeating group - needs explode to child rows")
        for x in vals:
            n_ = to_num(x)
            if n_ == "BAD":
                log("numeric_invalid", "ERROR", ref, row, c, v)
                break
            if n_ is not None and n_ < 0 and not re.search(r"Change|Difference|Net", c):
                log("numeric_negative", "WARN", ref, row, c, v)

# Repeating groups: array lengths must align within a row
ARRAY_GROUPS = {
    "Parking":         [c for c in fields if c.startswith("Parking") and c != "ParkingGroupID"],
    "ExistingHousing": [c for c in fields if c.startswith("ExistingHousing") and c != "ExistingHousingGroupID"],
    "ProposedHousing": [c for c in fields if c.startswith("ProposedHousing") and c != "ProposedHousingGroupID"],
}
for grp, cols in ARRAY_GROUPS.items():
    for i in df.index:
        lens = {c: len(split_array(df.at[i, c]) or [0]) for c in cols if not pd.isna(df.at[i, c])}
        if len(set(lens.values())) > 1:
            log("array_length_mismatch", "ERROR", df.at[i, CR], df.at[i, "_excel_row"], grp, lens,
                "Repeating group elements don't align")

for c in YESNO_COLS:
    for i, v in df[c].dropna().items():
        if str(v).strip().lower() not in ("yes", "no"):
            log("yes_no_invalid", "WARN", df.at[i, CR], df.at[i, "_excel_row"], c, v, "Not Yes/No - needs derivation")

EMAIL_RE = re.compile(r"^[^@\s;,]+@[^@\s;,]+\.[a-z]{2,}$", re.I)
PLACEHOLDERS = {"john.smith@lpa.co.uk"}
for c in EMAIL_COLS:
    for i, v in df[c].dropna().items():
        e = str(v).strip()
        ref, row = df.at[i, CR], df.at[i, "_excel_row"]
        if e.lower().startswith("mailto:"):
            log("email_mailto_prefix", "WARN", ref, row, c, e)
            e = e[7:]
        if e.lower() in PLACEHOLDERS:
            log("email_placeholder", "ERROR", ref, row, c, e, "Dummy/test value")
        elif not EMAIL_RE.match(e):
            log("email_invalid", "WARN", ref, row, c, e, "Invalid or multiple emails in one cell")

PC_RE = re.compile(r"^[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}$", re.I)
for c in POSTCODE_COLS:
    for i, v in df[c].dropna().items():
        if not PC_RE.match(str(v).strip()):
            log("postcode_invalid", "WARN", df.at[i, CR], df.at[i, "_excel_row"], c, v)

# 8. Enum distributions
enum_rows = []
for c in ENUM_COLS + YESNO_COLS:
    vc = df[c].fillna("<NULL>").astype(str).str.strip().value_counts()
    for val, cnt in vc.items():
        enum_rows.append({"column": c, "value": val, "count": int(cnt)})
enum_df = pd.DataFrame(enum_rows)

# near-duplicate enum values (case / whitespace variants)
for c in ENUM_COLS:
    vals = df[c].dropna().astype(str)
    norm = vals.str.strip().str.lower().str.replace(r"\s+", " ", regex=True)
    for k, g in vals.groupby(norm):
        if g.nunique() > 1:
            log("enum_case_variant", "WARN", column=c, value=" | ".join(g.unique()), detail="Same value, different casing/spacing")
